L END), 0)) > 1 THEN NULL ELSE SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0) END) > 1 THEN NULL ELSE CASE WHEN ABS(SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0)) > 1 THEN NULL ELSE SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0) END END - (LAG(CASE WHEN ABS(CASE WHEN ABS(SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0)) > 1 THEN NULL ELSE SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0) END) > 1 THEN NULL ELSE CASE WHEN ABS(SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0)) > 1 THEN NULL ELSE SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0) END END) OVER (ORDER BY date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP)) NULLS FIRST)) AS "!calc.ba7f9b17-f530-4bc0-9ba6-691b4981ad9b.0.0"
FROM (SELECT business_date, hierarchy_level, account, portfolio_type, department, strategy, program, sub_program, analytic_value, tenor, curve_type, analytic_name, analytic_type, node_level,rating,currency,node
FROM "risk_prod"."rmv_analytics"
WHERE analytic_type IN ('DV01', 'PV', 'CS01', 'VOLATILITY_10YR','VAR_10YR')
  AND portfolio_type IN ('TOTAL_FUND_BY_ACCOUNT', 'IP')
  and (confidence_level is null or confidence_level = 0.95)
  AND (
    (analytic_type IN ('PV', 'VOLATILITY_10YR','VAR_10YR') AND hierarchy_level IN ('CPPIB-ALL', 'DEPARTMENT', 'ACCOUNT', 'POOL', 'STRATEGY', 'PROGRAM', 'SUB-PROGRAM'))
    OR (analytic_type IN ('CS01', 'DV01') AND hierarchy_level = 'MODEL_PORTFOLIO')
  )) AS "New custom SQL"
WHERE "department" IN ('Total Fund Management') AND date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP)) = date_trunc('day', CAST(CAST(PARSE_DATETIME('2025-06-19 00:00:00', 'yyyy-MM-dd HH:mm:ss') AS TIMESTAMP) AS TIMESTAMP)) AND CASE WHEN "account" IS NULL AND "portfolio_type" = 'IP' THEN 'TOTAL FUND' ELSE "account" END IN ('TOTAL FUND') AND "analytic_type" IN ('VOLATILITY_10YR', 'PV') AND "hierarchy_level" = 'DEPARTMENT'
GROUP BY date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP))
ORDER BY date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP)) DESC
LIMIT 2

/* cppi::b1247c0061a53dc2ed87e7a5c2c52cb5632cb6d58c0444534e62d660e7b35952 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2025-01-02'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-01-02'
    ) a
where arrival_time = max_publish

/* cppi::b2143e7441fc4a45ffcf0d4dc5d3f702265a8ad4df9947a2be45a444bb58b356 */
select index_id, time_key, currency_code, geography, country_name, index_value, source_file
from (
        select *, max(last_publish) over (partition by index_id, time_key) max_publish
            from market.tfm_gdp_index
            where time_key between 1984 and 2030
            and last_publish <= date '2025-04-01'
    ) a
where last_publish = max_publish

/* cppi::5c0dbb9085b51684fbb59c5acaae4bf4aab7832438cc6b9073b742eb511e43a8 */
SELECT "SUBCOL" AS "COL"
FROM (
  SELECT 1 AS "SUBCOL"
) "SUBQUERY"
GROUP BY 1

/* cppi::7e302d73a6c6c0c552a02c81beb987e814c58f0ce4301734b7753cfa87806fbb */
select cusip, isin, ticker as issuer_code, issuer_name,coupon_rate as coupon, maturity_date as maturity, issue_date, interest_accrual_date, currency_code, country_code, null as classification_1, null as classification_2, null as classification_3, first_coupon_date, coupon_frequency_code as coupon_freq, inflation_linked_flag as inflation_linked, null as is_green, cppib_sec_id
            from asset.asset_bond_universe where ticker<>'WIT' and ticker<>'CMBR' and issuer_name not like 'WI%' and sub_type='GOVERNMENT' and cppib_sec_id is not null and maturity_date is not null and issue_date is not null  and delete_date is null

/* cppi::50892fa8292836b3419abdf5232652954f837c9dea4123c14c9e5662706faab8 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2025-04-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-04-01'
    ) a
where arrival_time = max_publish

/* cppi::9334b633b01fea3944f04a73f709b583afb3b321df58ecc6af5432d05cc48762 */
SELECT "COL"
FROM (SELECT 1 AS "COL") AS "SUBQUERY"

/* cppi::5c0dbb9085b51684fbb59c5acaae4bf4aab7832438cc6b9073b742eb511e43a8 */
SELECT "SUBCOL" AS "COL"
