/* cppi::545e82538cef7ac81c206335b19b73c6bc3d965aa7f2e7440528619d322638ce */
select dataset_id,business_date,time_weighted_return_fiscal_year_to_date_reporting_currency
from performance.scd_performance_bottom_up 
where dataset_id='TOTALFUND'
and business_date='2025-06-19' limit 500 -- {"user": "aluc@cppib.com", "source": "pyxll"}

/* cppi::55521b4cd286940d1d7af4278ef3d04be6f7c71ff0ee9b3cd76285ab8b4c062b */
select distinct external_reporting_assetmix,external_reporting_dm_em,external_reporting_region  from holdings.ma_holding_lookthrough 
where business_date =date'2025-06-19'

/* cppi::22a5914fe36c6e11a69ad49b58c7232b2e5a43a115f5ae3bbb02caf008b8fdf0 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-22' and end_date = '2025-05-22')
and start_date = '2025-05-22' and end_date = '2025-05-22'

